const HONORIFICS = new Set(['dr','prof','professor','mr','mrs','ms','miss','md']);
const BLOCKED_EMAIL_DOMAINS = new Set(['gmail.com','yahoo.com','hotmail.com','outlook.com','live.com','icloud.com','aol.com','proton.me','protonmail.com']);
const GENERIC_LOCAL_PARTS = new Set(['info','hello','hi','admin','support','contact','ask','enquiry','inquiry','office','sales','team','clinic','medical','feedback','service','appointment','appointments','booking','bookings','reception','general','marketing','hr','career','careers','privacy','dpo','compliance','it']);
function normaliseToken(value) { return String(value || '').toLowerCase().replace(/[^a-z0-9]/g, ''); }
function cleanNameToken(value) { return String(value || '').replace(/^[^A-Za-z]+|[^A-Za-z'-]+$/g, '').trim(); }
function stripHonorifics(value) {
  return String(value || '').replace(/\b(dr|dr\.|prof|prof\.|professor|mr|mr\.|mrs|mrs\.|ms|ms\.|miss|md)\b/gi, ' ').replace(/\s+/g, ' ').trim();
}
function titleCaseToken(value) {
  const cleaned = cleanNameToken(value);
  if (!cleaned) return '';
  if (/^[A-Z]\.?$/.test(cleaned)) return cleaned.replace(/\.$/, '') + '.';
  return cleaned.charAt(0).toUpperCase() + cleaned.slice(1).toLowerCase();
}
function splitNameTokens(value) {
  return stripHonorifics(value).split(/\s+/).map(titleCaseToken).filter(Boolean).filter((token) => !HONORIFICS.has(normaliseToken(token)));
}
