  const raw = String(url || '');
  const match = raw.match(/linkedin\.com\/(?:in|pub)\/([^/?#]+)/i);
  if (!match) return [];
  return decodeURIComponent(match[1]).split('-').map((part) => part.replace(/\d+$/, '').trim()).map(titleCaseToken).filter(Boolean);
}
function deriveNameParts({ fullName, firstName, lastName, linkedinUrl }) {
  const explicitFirst = splitNameTokens(firstName).join(' ');
  const explicitLast = splitNameTokens(lastName).join(' ');
  const sourceTokens = splitNameTokens(fullName).length ? splitNameTokens(fullName) : extractLinkedInSlugTokens(linkedinUrl);
  const normalizedFull = sourceTokens.join(' ');
  const normalizedFirst = explicitFirst || sourceTokens[0] || '';
  const normalizedLast = explicitLast || (sourceTokens.length > 1 ? sourceTokens[sourceTokens.length - 1] : '');
  return {
    full_name: normalizedFull || [normalizedFirst, normalizedLast].filter(Boolean).join(' '),
    first_name: normalizedFirst,
